<script lang="ts">
import { defineComponent, reactive, toRefs, watch, PropType, ref } from 'vue';
import { store as i18nStore } from 'plugins/i18n/store';
import { Ckeditor } from '@ckeditor/ckeditor5-vue';
import { ClassicEditor, Paragraph, Bold, Italic, List, Indent, Undo, Essentials } from 'ckeditor5';
// @ts-expect-error
import frTranslations from 'ckeditor5/translations/fr'

import 'ckeditor5/ckeditor5.css';

interface Data {
  internalValue?: string,
  editor: any,
  editorConfig: any,
}

const i18nLocale:Koddein.Locale = i18nStore.locale as Koddein.Locale;

const KoddeinFormWysiwyg = defineComponent({
  name: "KoddeinFormWysiwyg",
  components: {
    ckeditor: Ckeditor,
  },
  props: {
    id: {
      type: String,
      required: true,
    },
    placeholder: {
      type: String,
      default: undefined,
    },
    /** input value */
    value: {
      type: String,
      default: '',
    },
    /** toolbar options */
    toolbar: {
      type: Array as PropType<string[]>,
      default: undefined,
    },
    /** input error */
    error: {
      type: String,
      default: undefined,
    },
  },
  emits: ['inputChange', 'onFocus', 'onBlur'],
  setup(props, { emit }){
    const el = ref<any>()
    const data:Data = reactive(
      {
        /** @param {any} internalValue - clone value
         * - because we must not change props
         * - in `watch` will sync value within internalValue
         */
        internalValue: '<p>test</p>',
        editor: ClassicEditor,
        editorConfig: {
          initialData: '<p>test <b> bold</b></p>',
          toolbar: props.toolbar || ['bold', 'italic', 'bulletedList', 'numberedList', 'outdent', 'indent', 'undo'],
          plugins: [Essentials, Paragraph, Bold, Italic, List, Indent, Undo],
          language: {
            ui: i18nLocale?.name || 'en',
            content: i18nLocale?.name || 'en'
          },
          translations: [
            frTranslations
          ]
        }
      }
    );

    /**
     * Watch value, on value update -> set internal value
     */
    watch(
      ()=>props.value,
      (value) => { 
        data.internalValue = value ? value : '';
      },
      { immediate:true }
    )

    /**
     * Watch internal value, on value update -> send value to parent
     */
    watch(
      ()=>data.internalValue,
      (value) => { 
        // if (value === props.value) return;
        emit('inputChange', value);
      },
      // { immediate:true }
    )

    const focus = () => {
      emit('onFocus');
    }
    const blur = () => {
      emit('onBlur');
    }

    return {
      ...toRefs(data), //data
      el,
      locale: i18nLocale?.name || 'en',
      isFocus: focus,
      isBlur: blur,
    }; 
  },
});
export default KoddeinFormWysiwyg
</script>

<template>
  <div :class="error ? '-error' : ''"
       class="wrapper"
       @focus="isFocus"
       @blur="isBlur"
  >
    <ckeditor v-if="editor && editorConfig"
              ref="el"
              v-model="internalValue"
              :name="id"
              :editor="editor"
              :config="editorConfig"
              data-lenis-prevent
              tag-name="textarea"
              :placeholder="placeholder"
              class="input"
    />
  </div>
</template>

